"use client";

import { useEffect, useState } from "react";
import { apiGet, apiPost } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { useToast } from "@/hooks/use-toast";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Receipt, Search, FileText, MapPin, ChevronRight, Calendar, Clock, CreditCard, Plus, Loader2, Download } from "lucide-react";
import { formatDate, formatDateTime, formatMoney, formatUSDCompact } from "@/lib/constants";
import { exportToCSV } from "@/lib/csv-export";
import { ListStatsBar } from "@/components/app/list-stats-bar";

export function InvoiceList() {
  const { navigate, user } = useAppStore();
  const { toast } = useToast();
  const [invoices, setInvoices] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("Tất cả");
  const [showCreate, setShowCreate] = useState(false);
  const [createLoading, setCreateLoading] = useState(false);
  const [createForm, setCreateForm] = useState({ requestId: "", amount: "", currency: "VND", dueDate: "", notes: "" });
  const [approvedRequests, setApprovedRequests] = useState<any[]>([]);

  const isManager = user?.roleId === "LOGISTICS_MANAGER";

  const load = async () => {
    try { const d = await apiGet("/invoices"); setInvoices(d.invoices); }
    catch (e: any) { setError(e.message); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  // Load approved requests when create modal opens
  useEffect(() => {
    if (showCreate && isManager) {
      apiGet("/transport-requests?status=Đã phê duyệt").then((d) => setApprovedRequests(d.requests || [])).catch(() => {});
    }
  }, [showCreate, isManager]);

  const handleCreate = async () => {
    if (!createForm.requestId || !createForm.amount) { toast({ title: "Thiếu thông tin", description: "Vui lòng chọn đơn và nhập số tiền.", variant: "destructive" }); return; }
    setCreateLoading(true);
    try {
      await apiPost("/invoices", { ...createForm, amount: Number(createForm.amount) });
      toast({ title: "Đã tạo hóa đơn", description: "Hóa đơn mới đã được tạo và thông báo đến khách hàng." });
      setShowCreate(false);
      setCreateForm({ requestId: "", amount: "", currency: "VND", dueDate: "", notes: "" });
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setCreateLoading(false); }
  };

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = invoices.filter((inv) => {
    const matchSearch = !search || (inv.request?.competitionName || "").toLowerCase().includes(search.toLowerCase()) || inv.invoiceId.includes(search);
    const matchStatus = statusFilter === "Tất cả" || inv.paymentStatus === statusFilter;
    return matchSearch && matchStatus;
  });

  const handleExportCSV = () => {
    const headers = ["Mã hóa đơn", "Cuộc thi", "Khách hàng", "Tuyến", "Số tiền", "Loại tiền", "Trạng thái", "Hạn thanh toán", "Ngày phát hành", "Phương thức"];
    const rows = filtered.map((inv) => [
      inv.invoiceId.slice(-8).toUpperCase(),
      inv.request?.competitionName || "",
      inv.request?.customer?.name || "",
      `${inv.request?.origin?.name || ""} → ${inv.request?.destination?.name || ""}`,
      inv.amount,
      inv.currency,
      inv.paymentStatus,
      formatDate(inv.dueDate),
      formatDate(inv.issuedAt),
      inv.paymentMethod || "",
    ]);
    exportToCSV(`equideli-hoa-don-${new Date().toISOString().slice(0, 10)}.csv`, headers, rows);
    toast({ title: "Đã xuất CSV", description: `${rows.length} hóa đơn đã được tải xuống.` });
  };

  const totalAmount = invoices.reduce((s, inv) => s + (inv.amount || 0), 0);
  const paidAmount = invoices.filter((i) => i.paymentStatus === "Đã thanh toán").reduce((s, inv) => s + (inv.amount || 0), 0);
  const unpaidAmount = totalAmount - paidAmount;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Hóa đơn & Thanh toán"
        description={isManager ? "Quản lý hóa đơn và theo dõi thanh toán" : "Hóa đơn và lịch sử thanh toán của bạn"}
        icon={<Receipt className="h-5 w-5" />}
        actions={
          <div className="flex items-center gap-2">
            <div className="relative w-full sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm hóa đơn..." className="pl-9" /></div>
            <Button variant="outline" size="sm" onClick={handleExportCSV} disabled={filtered.length === 0} className="gap-1.5"><Download className="h-4 w-4" /> <span className="hidden sm:inline">Xuất CSV</span></Button>
            {isManager && <Button onClick={() => setShowCreate(true)} className="gap-2 btn-press"><Plus className="h-4 w-4" /> Tạo hóa đơn</Button>}
          </div>
        }
      />

      {/* Create invoice modal */}
      {showCreate && (
        <Card className="border-primary/30 animate-fade-in-up">
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Plus className="h-4 w-4" /> Tạo hóa đơn mới</CardTitle></CardHeader>
          <CardContent className="space-y-3">
            <div className="space-y-2">
              <Label>Đơn vận chuyển</Label>
              <select value={createForm.requestId} onChange={(e) => {
                const req = approvedRequests.find((r) => r.requestId === e.target.value);
                setCreateForm({ ...createForm, requestId: e.target.value, amount: req?.estimatedAmount ? String(req.estimatedAmount) : "", currency: req?.currency || "VND" });
              }} className="flex h-10 w-full rounded-md border border-input bg-background px-3 text-sm">
                <option value="">— Chọn đơn đã phê duyệt —</option>
                {approvedRequests.map((r) => <option key={r.requestId} value={r.requestId}>{r.competitionName || `Đơn #${r.requestId.slice(-8)}`} — {r.customer?.name}{r.estimatedAmount ? ` (${formatMoney(r.estimatedAmount, r.currency)})` : ""}</option>)}
              </select>
              <p className="text-xs text-muted-foreground">Chọn đơn vận chuyển để gắn hóa đơn. Hệ thống sẽ tự động thông báo cho khách hàng.</p>
            </div>
            <div className="grid gap-3 sm:grid-cols-3">
              <div className="space-y-2"><Label>Số tiền</Label><Input type="number" value={createForm.amount} onChange={(e) => setCreateForm({ ...createForm, amount: e.target.value })} placeholder="0" /></div>
              <div className="space-y-2"><Label>Loại tiền</Label><select value={createForm.currency} onChange={(e) => setCreateForm({ ...createForm, currency: e.target.value })} className="flex h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option>VND</option><option>JPY</option><option>USD</option></select></div>
              <div className="space-y-2"><Label>Hạn thanh toán</Label><Input type="date" value={createForm.dueDate} onChange={(e) => setCreateForm({ ...createForm, dueDate: e.target.value })} /></div>
            </div>
            <div className="space-y-2"><Label>Ghi chú</Label><Textarea value={createForm.notes} onChange={(e) => setCreateForm({ ...createForm, notes: e.target.value })} rows={2} placeholder="Ghi chú cho khách hàng..." /></div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowCreate(false)}>Hủy</Button>
              <Button onClick={handleCreate} disabled={createLoading} className="gap-2">{createLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />} Tạo hóa đơn</Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Summary cards */}
      <div className="grid gap-4 sm:grid-cols-3">
        <Card><CardContent className="p-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 text-primary"><Receipt className="h-5 w-5" /></div><div><p className="text-xs text-muted-foreground">Tổng giá trị</p><p className="text-lg font-bold">{formatUSDCompact(totalAmount)}</p></div></div></CardContent></Card>
        <Card><CardContent className="p-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[var(--success-bg)] text-[var(--success-fg)]"><CreditCard className="h-5 w-5" /></div><div><p className="text-xs text-muted-foreground">Đã thanh toán</p><p className="text-lg font-bold text-[var(--success-fg)]">{formatUSDCompact(paidAmount)}</p></div></div></CardContent></Card>
        <Card><CardContent className="p-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[var(--warning-bg)] text-[var(--warning-fg)]"><Clock className="h-5 w-5" /></div><div><p className="text-xs text-muted-foreground">Chưa thanh toán</p><p className="text-lg font-bold text-[var(--warning-fg)]">{formatUSDCompact(unpaidAmount)}</p></div></div></CardContent></Card>
      </div>

      {/* Status filters */}
      <div className="flex flex-wrap gap-1.5">
        {["Tất cả", "Chưa thanh toán", "Đang xử lý", "Đã thanh toán", "Quá hạn"].map((s) => (
          <button key={s} onClick={() => setStatusFilter(s)} className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${statusFilter === s ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/70"}`}>{s}</button>
        ))}
      </div>

      {/* Stats overview */}
      <ListStatsBar
        total={invoices.length}
        filtered={filtered.length}
        stats={[
          { label: "Đã thanh toán", value: invoices.filter((i) => i.paymentStatus === "Đã thanh toán").length, tone: "success" },
          { label: "Chưa thanh toán", value: invoices.filter((i) => i.paymentStatus !== "Đã thanh toán").length, tone: "warning" },
          { label: "Tổng giá trị", value: formatMoney(totalAmount) },
        ]}
      />

      {filtered.length === 0 ? (
        <EmptyState illustration="no-data" title="Không có hóa đơn" description="Hóa đơn sẽ được tạo khi đơn vận chuyển được phê duyệt." />
      ) : (
        <div className="space-y-3">
          {filtered.map((inv) => (
            <button key={inv.invoiceId} onClick={() => navigate("invoice-detail", { id: inv.invoiceId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Receipt className="h-6 w-6" /></div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{inv.request?.competitionName || `Hóa đơn #${inv.invoiceId.slice(-8)}`}</p>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  {isManager && <span>{inv.request?.customer?.name}</span>}
                  <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{inv.request?.origin?.name} → {inv.request?.destination?.name}</span>
                  <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />Phát hành: {formatDate(inv.issuedAt)}</span>
                  {inv.dueDate && <span className="flex items-center gap-1"><Clock className="h-3 w-3" />Hạn: {formatDate(inv.dueDate)}</span>}
                </div>
              </div>
              <div className="flex flex-col items-end gap-1.5">
                <StatusBadge status={inv.paymentStatus} />
                <span className="text-sm font-bold text-foreground">{formatMoney(inv.amount, inv.currency)}</span>
              </div>
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
